import {resolveTakeRate,takeRateAllowsDrop,formatTakeTimecode,parseTakeTimecode} from './take-clock.js';

export function timelineRate(data){return resolveTakeRate(data.displayRate??data.fps??60);}
export function timelineFPS(data){const r=timelineRate(data);return r.numerator/r.denominator;}
export function validTimelineRate(data){try{if(data.displayRate!==undefined&&(!data.displayRate||typeof data.displayRate!=='object'||Array.isArray(data.displayRate)))return false;const r=timelineRate(data);return (data.displayDropFrame===undefined||typeof data.displayDropFrame==='boolean')&&(!data.displayDropFrame||takeRateAllowsDrop(r));}catch{return false;}}
export function configureTimelineRate(data,rate,dropFrame=false){const next={...data};if(rate===null){delete next.displayRate;delete next.displayDropFrame;}else{next.displayRate=resolveTakeRate(rate);next.displayDropFrame=dropFrame;}if(!validTimelineRate(next))throw Error('편집 격자 분수·드롭 프레임 설정을 확인하세요.');if(rate===null){delete data.displayRate;delete data.displayDropFrame;}else{data.displayRate=next.displayRate;data.displayDropFrame=next.displayDropFrame;}}
const nearInteger=value=>{const nearest=Math.round(value);return Math.abs(value-nearest)<=8*Number.EPSILON*Math.max(1,Math.abs(value))?nearest:value;};
export function timelineFrameAt(data,time,mode='round'){if(!Number.isFinite(time)||!['round','floor','ceil'].includes(mode))throw Error('타임라인 시간·프레임 반올림 방식을 확인하세요.');const r=timelineRate(data),value=nearInteger(time*r.numerator/r.denominator);const frame=Math[mode](value);if(!Number.isSafeInteger(frame))throw Error('편집 프레임 범위를 확인하세요.');return frame;}
export function timelineFrameTime(data,frame){if(!Number.isSafeInteger(frame))throw Error('편집 프레임은 안전한 정수로 입력하세요.');const r=timelineRate(data);return frame*r.denominator/r.numerator;}
export function timelineSnap(data,time){return timelineFrameTime(data,timelineFrameAt(data,time));}
export function timelineStep(data,time,direction){if(![-1,1].includes(direction))throw Error('프레임 이동 방향을 확인하세요.');return timelineFrameTime(data,timelineFrameAt(data,time,direction>0?'floor':'ceil')+direction);}
export function timelineTimecode(data,time){return formatTakeTimecode(Math.max(0,timelineFrameAt(data,time)),timelineRate(data),{dropFrame:data.displayDropFrame??false});}
export function timelineParseTimecode(data,text){return timelineFrameTime(data,parseTakeTimecode(text,timelineRate(data),{dropFrame:data.displayDropFrame??false}));}
export const timelineRateContract={fields:'sequence.displayRate?:{numerator,denominator}, displayDropFrame?:boolean; absent follows legacy integer fps',range:'Reduced positive int32 rational 1..240 FPS; DF only30000/1001 or60000/1001; old integer fps and recordingClock.rate remain independent',authoring:'Ruler, frame/timecode transport, frame stepping, clip/key/section dragging, range handles and sequence curve default bake share the rational rate; Shift drag keeps free seconds',storage:'Keys, clips, playback rate and sequence length stay in seconds; changing displayRate never retimes content; document.patch uses ordinary expectedRevision/dryRun/Undo/save',runtime:'LevelSequence SeekFrame/GetFrame/GetFrameRateNumerator/GetFrameRateDenominator use the loaded sequence display rate; frame seek clamps only the final partial frame to length; no active sequence returns0 for getters',remaining:['external timecode/genlock device integration','per-channel time inheritance']};
